head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > selectedRowOverColor]<br/>마우스 포인터가 포커스된 Body Row 에 오버될때 Row 의 배경색으로 적용될 색상을 설정합니다. rowMouseOver=true 이고 focusMode='row','both' 인 경우에 동작합니다.",
    "validation" : [
        "마우스 포인터가 포커스된 Body Row 에 오버될때 Row 의 배경색으로 적용될 색상을 설정합니다. rowMouseOver=true 이고 focusMode='row','both' 인 경우에 동작합니다.",
        "색상은 색상이름('blue','red'), 색상코드('#rrggbb'), 함수형 색상('rgb(...)','rgba(...)') 등 다양한 형식으로 설정 가능합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정 (con_ 옵션을 properties 객체로 모아 createCList 로 속성 문자열 생성, 빈값 자동 제외)
    //  - rowMouseOver 는 본 샘플 검증 전제이므로 "true" 하드코딩, 옵션으로 노출하지 않음
    //  - focusMode 는 selectedRowOverColor 가 동작하는 모드(row/both) 중 "both" 하드코딩
    //  - selectedCellOverColor 는 포커스 Cell(selectedCellOverColor) 과 동일 Row 다른 Cell(selectedRowOverColor) 의 대비 가시화를 위해 기본 색 부여
    let properties = {
        dataList             : "data:dlt_bind",
        focusMode            : "both",
        rowMouseOver         : "true",
        selectedCellOverColor: "orange",
        selectedRowOverColor : con_selectedRowOverColor.getValue()
    };
    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onbodymouseover"]);

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    let lblRowOver = (properties.selectedRowOverColor === '') ? '미설정' : properties.selectedRowOverColor;
    $c.gcm.createLabel('label="rowMouseOver=true / focusMode=both (고정) / selectedRowOverColor=' + lblRowOver + ' 로 GridView 생성. setFocusedCell 로 포커스 후 해당 Row 에 마우스를 오버하면 포커스 Cell 은 selectedCellOverColor(orange), 같은 Row 다른 Cell 은 selectedRowOverColor 가 적용됨"', '', 'label1');

    // dataList 생성 (헬퍼와 동일하게 col1~col4 컬럼 구성)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성
    await $c.gcm.createBasicGridView(cList, eList);
}



// 특정 Row(rowIndex) 의 각 셀 computed 배경색(rgb 형식) 을 셀별로 합쳐 반환
//  - focusMode=both 마우스 오버 시 포커스 Cell 은 selectedCellOverColor, 같은 Row 다른 Cell 은 selectedRowOverColor 적용
scwin.getRowBgColor = function (rowIndex) {
    let colCnt = 4;
    let colors = [];
    for (let c = 0; c < colCnt; c++) {
        let td = document.querySelector("td[id*='target1_cell_" + rowIndex + "_" + c + "']");
        colors.push("col" + c + "=" + (td ? window.getComputedStyle(td).backgroundColor : "(셀 없음)"));
    }
    return colors.join(" / ");
}



// 지정한 Body Cell 을 포커스시키는 사전상태 설정 (마우스 오버는 사용자 동작으로 수행)
//  - rowIndex/colIndex 는 par_ 콤보에서 선택
scwin.btn_setFocusedCell_onclick = function () {
    let rowIndex = parseInt(par_rowIndex.getValue(), 10);
    let colIndex = parseInt(par_colIndex.getValue(), 10);

    // DataList currentRow 정합성 유지
    dlt_bind.setRowPosition(rowIndex);
    target1.setFocusedCell(rowIndex, colIndex);

    wf_body_bottom.getObj("scwin").setReturnValue("[포커스 설정] Cell(" + rowIndex + "," + colIndex + ") 포커스. 해당 Row 에 마우스를 오버하세요.");
}



// 포커스된 Row 에 마우스가 오버되면 자동 출력 (onbodymouseover)
//  - focusMode='both' 이므로 포커스 Cell 은 selectedCellOverColor(orange), 동일 Row 의 다른 Cell 은 selectedRowOverColor 적용 기대
//  - 포커스 Row 의 각 셀 computed 배경색을 셀별로 출력 → 포커스 Cell 과 그 외 Cell 의 색 차이로 selectedRowOverColor 적용 확인
scwin.target1_onbodymouseover = function (info) {
    let rowIndex = target1.getFocusedRowIndex();
    let colIndex = target1.getFocusedColumnIndex();
    // 포커스된 Cell 이 없으면 출력하지 않음
    if (rowIndex === null || rowIndex === undefined || rowIndex < 0 ||
        colIndex === null || colIndex === undefined || colIndex < 0) {
        return;
    }

    // 포커스된 Row 에 오버된 경우에만 출력
    if (info.rowIndex !== rowIndex) {
        return;
    }

    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onbodymouseover (포커스 Row " + rowIndex + " 오버)=====");
    wf_body_bottom.getObj("scwin").setReturnValue("[포커스 Row(" + rowIndex + ") 셀별 배경색 / 포커스 Cell(col" + colIndex + ")=selectedCellOverColor, 그 외=selectedRowOverColor] " + scwin.getRowBgColor(rowIndex));
}
